"""Seam coverage for 直接顯示候選字清單 (``directShowCand``, upstream #438).

With the option on, one session must give both halves of the selection flow:

* a key whose code is unique still commits its lone candidate;
* a colliding key opens the normal candidate window, space turns pages and the
  selection keys pick from the page that is on screen.

Each case drives the real 速成 (chesimplex) service — the one that ships
``directShowCand: true`` — with synthesized key events.
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402


class CinbaseDirectShowCandTests(CinbaseKeyHarness):

    def set_page_size(self, service, size):
        service.candPerPage = size
        service.candidateView.configure(size, service.candPerRow)

    def test_direct_show_lone_candidate_commits_with_space(self):
        service = self.activate_chesimplex()
        self.assertTrue(service.directShowCand, "setup: 速成 ships directShowCand")

        self.send(service, ord("b"), ord("b"), printable=True)
        self.assertTrue(service.isShowCandidates)
        self.assertEqual(list(service.candidateList), ["月"])

        self.assertEqual(self.send(service, 0x20, 0x20), "月")
        self.assertFalse(service.isComposing())

    def test_direct_show_paging_then_pick_from_second_page(self):
        service = self.activate_chesimplex()
        self.assertTrue(service.directShowCand, "setup: 速成 ships directShowCand")
        service.switchPageWithSpace = True
        self.set_page_size(service, 2)

        # 速成 "l" holds three candidates: 中 丨 丿
        self.send(service, ord("l"), ord("l"), printable=True)
        self.assertTrue(service.isShowCandidates)
        self.assertEqual(list(service.candidateList), ["中", "丨"])

        self.send(service, 0x20, 0x20)  # space turns the page
        self.assertEqual(list(service.candidateList), ["丿"],
                         "space did not page the direct-show window")

        self.assertEqual(self.send(service, ord("1"), printable=True), "丿")
        self.assertFalse(service.isComposing())

    def test_direct_show_both_halves_in_one_session(self):
        # The report's point: the option used to give either the lone-candidate
        # commit or the paged pick, never both in one session.
        service = self.activate_chesimplex()
        service.switchPageWithSpace = True
        self.set_page_size(service, 2)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0x20, 0x20)
        self.assertEqual(self.send(service, ord("1"), printable=True), "丿")

        self.send(service, ord("b"), ord("b"), printable=True)
        self.assertEqual(list(service.candidateList), ["月"])
        self.assertEqual(self.send(service, 0x20, 0x20), "月")

    def test_direct_show_arrow_keys_move_the_cursor(self):
        service = self.activate_chesimplex()
        self.set_page_size(service, 2)

        self.send(service, ord("l"), ord("l"), printable=True)
        self.send(service, 0, 0x27)  # VK_RIGHT
        self.assertEqual(service.candidateView.cursor, 1)
        self.assertEqual(self.send(service, 0x20, 0x20), "丨")


if __name__ == "__main__":
    unittest.main()
